# Test that nest_toc_tokens works with TocToken
from collections import UserDict

class TocToken(UserDict):
    EXTRA_KEYS = {'html', 'data-toc-label'}

    def __eq__(self, other):
        if isinstance(other, dict):
            for key in ('level', 'id', 'name', 'children'):
                self_val = self.get(key)
                other_val = other.get(key)
                if key == 'children':
                    if not isinstance(self_val, list) or not isinstance(other_val, list):
                        return False
                    if len(self_val) != len(other_val):
                        return False
                    for s, o in zip(self_val, other_val):
                        if not _compare_token(s, o):
                            return False
                else:
                    if self_val != other_val:
                        return False
            return True
        return super().__eq__(other)

    def __ne__(self, other):
        return not self.__eq__(other)

def _compare_token(token, expected):
    if isinstance(token, dict):
        for key in ('level', 'id', 'name', 'children'):
            t_val = token.get(key)
            e_val = expected.get(key)
            if key == 'children':
                if not isinstance(t_val, list) or not isinstance(e_val, list):
                    return False
                if len(t_val) != len(e_val):
                    return False
                for s, o in zip(t_val, e_val):
                    if not _compare_token(s, o):
                        return False
            else:
                if t_val != e_val:
                    return False
        return True
    elif hasattr(token, '__getitem__'):
        return _compare_token(dict(token), expected)
    return False

def nest_toc_tokens(toc_list):
    """Same as original"""
    ordered_list = []
    if len(toc_list):
        last = toc_list.pop(0)
        last['children'] = []
        levels = [last['level']]
        ordered_list.append(last)
        parents = []
        while toc_list:
            t = toc_list.pop(0)
            current_level = t['level']
            t['children'] = []
            if current_level < levels[-1]:
                levels.pop()
                to_pop = 0
                for p in reversed(parents):
                    if current_level <= p['level']:
                        to_pop += 1
                    else:
                        break
                if to_pop:
                    levels = levels[:-to_pop]
                    parents = parents[:-to_pop]
                levels.append(current_level)
            if current_level == levels[-1]:
                (parents[-1]['children'] if parents else ordered_list).append(t)
            else:
                last['children'].append(t)
                parents.append(last)
                levels.append(current_level)
            last = t
    return ordered_list

# Test nesting with TocTokens
tokens = [
    TocToken({'level': 5, 'id': 'some-header', 'name': 'Some Header', 'html': '<div>Some Header</div>', 'data-toc-label': None}),
    TocToken({'level': 6, 'id': 'next-level', 'name': 'Next Level', 'html': '<div>Next Level</div>', 'data-toc-label': None}),
    TocToken({'level': 6, 'id': 'too-high', 'name': 'Too High', 'html': '<div>Too High</div>', 'data-toc-label': None}),
]

nested = nest_toc_tokens(tokens)
print(f"Nested result: {nested}")
print(f"Type of first entry: {type(nested[0])}")
print(f"First entry keys: {list(nested[0].keys())}")
print(f"Children type: {type(nested[0]['children'][0])}")

expected = {
    'level': 5, 'id': 'some-header', 'name': 'Some Header', 'children': [
        {'level': 6, 'id': 'next-level', 'name': 'Next Level', 'children': []},
        {'level': 6, 'id': 'too-high', 'name': 'Too High', 'children': []},
    ]
}
print(f"Equality with expected: {nested[0] == expected}")
